function fileUp(string $key,string $prefix):?string{
 if(empty($_FILES[$key]['name']))return null;
 if($_FILES[$key]['error']!==UPLOAD_ERR_OK||$_FILES[$key]['size']>8388608)throw new Exception('Archivo inválido o mayor a 8 MB.');
 $mime=(new finfo(FILEINFO_MIME_TYPE))->file($_FILES[$key]['tmp_name']);$ext=['application/pdf'=>'pdf','image/jpeg'=>'jpg','image/png'=>'png'][$mime]??null;
 if(!$ext)throw new Exception('Solo se permiten PDF, JPG o PNG.');
 $name=$prefix.'-'.bin2hex(random_bytes(8)).'.'.$ext;
 $root=dirname(__DIR__,3);
 if(!move_uploaded_file($_FILES[$key]['tmp_name'],$root.'/storage/uploads/'.$name))throw new Exception('No se pudo guardar el archivo.');
 return 'storage/uploads/'.$name;
}
