<div class="actions"><div style="flex:1"><span class="muted"><?=e($p['business_name'])?><?php if($p['partner_name']):?> · <?=e($p['partner_name'])?><?php endif;?></span><h1><?=e($p['project_number'])?> · <?=e($p['name'])?></h1></div><?php if(isAdmin()):?><a class="btn light" href="?a=edit_project&id=<?=$id?>">Editar proyecto</a><?php endif;?><span class="pill"><?=e($p['status'])?></span></div><?php foreach(['ARS','USD'] as $cur):if($totals[$cur]['total']<.009&&$totals[$cur]['paid']<.009)continue;?><h2><?=e($cur)?></h2><div class="grid"><div class="card c4"><span class="muted">Total vigente</span><div class="kpi"><?=mon($totals[$cur]['total'],$cur)?></div></div><div class="card c4"><span class="muted">Pagado</span><div class="kpi ok"><?=mon($totals[$cur]['paid'],$cur)?></div></div><div class="card c4"><span class="muted">Saldo</span><div class="kpi bad"><?=mon($totals[$cur]['total']-$totals[$cur]['paid'],$cur)?></div></div></div><div class="grid"><div class="card c6"><h3>Materiales</h3><p>Total: <b><?=mon($totals[$cur]['materials'],$cur)?></b> · Imputado: <span class="ok"><?=mon($totals[$cur]['materials_paid'],$cur)?></span></p></div><div class="card c6"><h3>Mano de obra e ingeniería</h3><p>Total: <b><?=mon($totals[$cur]['labor'],$cur)?></b> · Imputado: <span class="ok"><?=mon($totals[$cur]['labor_paid'],$cur)?></span></p></div></div><?php endforeach;?>
<div class="card"><div class="actions"><h2 style="flex:1">Presupuestos por rubro</h2><?php if(isAdmin()):?><a class="btn light" href="?a=new_quote&project_id=<?=$id?>">+ Agregar presupuesto</a><?php endif;?></div><p class="muted">Podés cargar por separado Domótica, Redes, Cámaras, Alarma y Audio. Cada presupuesto conserva su moneda, PDF, IVA, Materiales y Mano de obra.</p><div class="scroll"><table><tr><th>Rubro</th><th>Versión</th><th>Fecha</th><th>Estado</th><th>Moneda</th><th class="right">Materiales</th><th class="right">Mano de obra</th><th>IVA</th><th class="right">Total</th><th>Archivo</th></tr><?php $categoryLabels=['general'=>'General / anterior','domotica'=>'Domótica','redes'=>'Redes','camaras'=>'Cámaras','alarma'=>'Alarma','audio'=>'Audio'];$taxLabels=['sin_iva'=>'Sin IVA','iva_incluido'=>'IVA incluido','mas_iva'=>'Más IVA'];foreach($quotes as $r):?><tr><td><span class="pill"><?=e($categoryLabels[$r['quote_category']]??$r['quote_category'])?></span></td><td>v<?=$r['version_no']?></td><td><?=e($r['quote_date'])?></td><td><span class="pill"><?=e($r['status'])?></span></td><td><span class="pill"><?=e($r['currency'])?></span></td><td class="right"><?=mon($r['materials_amount'],$r['currency'])?></td><td class="right"><?=mon($r['labor_amount'],$r['currency'])?></td><td><?=e($taxLabels[$r['tax_mode']]??$r['tax_mode'])?></td><td class="right"><b><?=mon($r['total'],$r['currency'])?></b></td><td><?=$r['file_path']?'<a target="_blank" href="'.e($r['file_path']).'">Ver PDF</a>':'—'?></td></tr><?php endforeach;?></table></div></div>
<div class="card"><div class="actions"><h2 style="flex:1">Cargos</h2><?php if(isAdmin()):?><a class="btn light" href="?a=new_charge&project_id=<?=$id?>">+ Cargo</a><?php endif;?></div><div class="scroll"><table><tr><th>Fecha</th><th>Concepto</th><th>Moneda</th><th class="right">Importe</th><th class="right">Imputado</th><th class="right">Pendiente</th></tr><?php foreach($charges as $r):?><tr style="<?=$r['active']?'':'opacity:.45'?>"><td><?=e($r['charge_date'])?></td><td><span class="pill"><?=e($r['type'])?></span> <?=e($r['description'])?> <?=$r['active']?'':'(absorbido)'?></td><td><?=e($r['currency'])?></td><td class="right"><?=mon($r['amount'],$r['currency'])?></td><td class="right"><?=mon($r['paid'],$r['currency'])?></td><td class="right"><b><?=mon($r['active']?$r['amount']-$r['paid']:0,$r['currency'])?></b></td></tr><?php endforeach;?></table></div></div>
<div class="card"><div class="actions"><h2 style="flex:1">Pagos y recibos</h2><?php if(isAdmin()):?><a class="btn" href="?a=new_payment&project_id=<?=$id?>">+ Registrar pago y generar recibo</a><?php endif;?></div><div class="scroll"><table><tr><th>Fecha / recibo</th><th>Medio</th><th>Moneda</th><th class="right">Pago</th><th class="right">Imputado</th><th>Acciones</th></tr><?php foreach($payments as $r):?><tr><td><?=e($r['payment_date'])?><br><b><?=e($r['receipt_number'])?></b></td><td><?=e($r['method'])?> · <?=e($r['reference'])?></td><td><?=e($r['currency'])?></td><td class="right"><b><?=mon($r['amount'],$r['currency'])?></b></td><td class="right"><?=mon($r['allocated'],$r['currency'])?></td><td><div class="actions"><a class="btn light" target="_blank" href="?a=receipt&id=<?=$r['id']?>">Ver recibo</a><?php if(isAdmin()&&$r['email']):?><form method="post" action="?a=send_receipt_email"><?=token()?><input type="hidden" name="payment_id" value="<?=$r['id']?>"><button class="btn light">Email</button></form><?php endif;?><?php if($r['whatsapp']):?><a class="btn light" target="_blank" href="?a=receipt_whatsapp&id=<?=$r['id']?>">WhatsApp</a><?php endif;?></div><?php if($r['email_sent_at']):?><small class="muted">Email: <?=e($r['email_sent_at'])?></small><?php endif;?><?php if($r['whatsapp_opened_at']):?><small class="muted"> · WhatsApp: <?=e($r['whatsapp_opened_at'])?></small><?php endif;?></td></tr><?php endforeach;?></table></div></div>
<?php }}elseif($a==='new_quote'){$pid=(int)$_GET['project_id'];$s=$db->prepare('SELECT p.*,COALESCE(MAX(q.version_no),0)+1 nextv FROM projects p LEFT JOIN quotes q ON q.project_id=p.id WHERE p.id=? GROUP BY p.id');$s->execute([$pid]);$p=$s->fetch();?><div class="card"><h1>Agregar presupuesto</h1><p class="muted"><?=e($p['project_number']??'')?> · Elegí el rubro, la moneda y la condición de IVA de este presupuesto.</p><form method="post" action="?a=save_quote" enctype="multipart/form-data"><?=token()?><input type="hidden" name="project_id" value="<?=$pid?>"><div class="grid"><p class="c4"><label>Rubro del presupuesto</label><select name="quote_category" required><option value="">Seleccionar…</option><option value="domotica">Domótica</option><option value="redes">Redes</option><option value="camaras">Cámaras</option><option value="alarma">Alarma</option><option value="audio">Audio</option></select></p><p class="c2"><label>Versión</label><input type="number" name="version_no" value="<?=$p['nextv']?>" required></p><p class="c3"><label>Moneda</label><select name="currency" required><option value="ARS">Pesos argentinos ($)</option><option value="USD">Dólares estadounidenses (US$)</option></select></p>
<p class="c3"><label>Fecha</label><input type="date" name="quote_date" value="<?=date('Y-m-d')?>" required></p>
<p class="c3"><label>Materiales</label><input type="number" step=".01" min="0" name="materials_amount" required></p>
<p class="c3"><label>Mano de obra</label><input type="number" step=".01" min="0" name="labor_amount" required></p>
