<p class="c4"><label>IVA</label><select name="tax_mode"><option value="sin_iva">Sin IVA</option><option value="iva_incluido">IVA incluido</option><option value="mas_iva">Más IVA</option></select></p>
<p class="c4"><label>Alícuota %</label><input type="number" step=".01" name="vat_rate" value="<?=e($p['vat_rate'])?>"></p>
