<?php }elseif($a==='new_payment'){$pid=(int)$_GET['project_id'];$s=$db->prepare('SELECT project_number,name FROM projects WHERE id=?');$s->execute([$pid]);$paymentProject=$s->fetch();$s=$db->prepare('SELECT c.*,COALESCE(SUM(a.amount),0) paid FROM charges c LEFT JOIN allocations a ON a.charge_id=c.id WHERE c.project_id=? AND c.active=1 GROUP BY c.id HAVING c.amount-paid>0.009');$s->execute([$pid]);$charges=$s->fetchAll();?><div class="card"><h1>Registrar pago y generar recibo</h1><p class="muted"><?=e($paymentProject['project_number']??'')?> · <?=e($paymentProject['name']??'')?>. Elegí la moneda del pago; solo podrá imputarse a cargos de esa misma moneda.</p><form method="post" action="?a=save_payment" enctype="multipart/form-data"><?=token()?><input type="hidden" name="project_id" value="<?=$pid?>"><div class="grid"><p class="c3"><label>Fecha</label><input type="date" name="payment_date" value="<?=date('Y-m-d')?>" required></p><p class="c3"><label>Moneda</label><select name="currency" id="payment-currency" required onchange="filterCharges()"><option value="ARS">Pesos argentinos ($)</option><option value="USD">Dólares estadounidenses (US$)</option></select></p>
<p class="c3"><label>Importe</label><input type="number" min=".01" step=".01" name="amount" required></p>
<p class="c3"><label>Medio</label><select name="method"><option value="transferencia">Transferencia</option><option value="efectivo">Efectivo</option><option value="cheque">Cheque</option><option value="tarjeta">Tarjeta</option><option value="otro">Otro</option></select></p>
<p class="c3"><label>Referencia</label><input name="reference"></p>
<p class="c6"><label>Comprobante</label><input type="file" name="receipt" accept=".pdf,.jpg,.jpeg,.png"></p>
<p class="c12"><label>Notas</label><textarea name="notes"></textarea></p></div><h3>Asignación del pago</h3><p class="muted">Indicá cuánto corresponde a cada concepto de la moneda seleccionada.</p><table><tr><th>Concepto</th><th class="right">Pendiente</th><th>Monto a asignar</th></tr><?php foreach($charges as $c):$due=$c['amount']-$c['paid'];?><tr class="charge-row" data-currency="<?=e($c['currency'])?>"><td><span class="pill"><?=e($c['type'])?></span> <?=e($c['description'])?></td><td class="right"><?=mon($due,$c['currency'])?></td><td style="width:200px"><input class="allocation" type="number" min="0" max="<?=$due?>" step=".01" name="alloc[<?=$c['id']?>]" value="0"></td></tr><?php endforeach;?></table><br><button class="btn">Guardar pago y generar recibo</button></form><script>function filterCharges(){const cur=document.getElementById('payment-currency').value;document.querySelectorAll('.charge-row').forEach(row=>{const show=row.dataset.currency===cur;row.style.display=show?'':'none';if(!show)row.querySelector('.allocation').value=0;});}filterCharges();</script></div>
<?php }elseif($a==='users'&&isAdmin()){$users=$db->query('SELECT * FROM users ORDER BY name')->fetchAll();?><div class="grid"><div class="card c8"><h1>Usuarios</h1><table><tr><th>Nombre</th><th>Email</th><th>Rol</th></tr><?php foreach($users as $u):?><tr><td><?=e($u['name'])?></td><td><?=e($u['email'])?></td><td><?=e($u['role'])?></td></tr><?php endforeach;?></table></div><div class="card c4"><h2>Nuevo usuario</h2><form method="post" action="?a=save_user"><?=token()?><p><label>Nombre</label><input name="name" required></p>
<p><label>Email</label><input type="email" name="email" required></p>
<p><label>Clave</label><input type="password" minlength="8" name="password" required></p>
<p><label>Rol</label><select name="role"><option value="admin">Administrador</option><option value="consulta">Solo consulta</option></select></p><button class="btn">Crear</button></form></div></div><?php }
